    RectTransform CreateForgeActor(
        Transform parent,
        string name,
        Sprite sprite,
        Vector2 anchor,
        Vector2 size,
        out Image image
    )
    {
        GameObject go = new GameObject(
            name,
            typeof(RectTransform),
            typeof(CanvasRenderer),
            typeof(Image)
        );
        go.transform.SetParent(parent, false);
        image = go.GetComponent<Image>();
        image.sprite = sprite;
        image.color = sprite != null ? Color.white : new Color(.25f, .25f, .25f, 1f);
        image.preserveAspect = true;
        image.raycastTarget = false;

        RectTransform rt = image.rectTransform;
        rt.anchorMin = rt.anchorMax = anchor;
        rt.pivot = new Vector2(.5f, .5f);
        rt.sizeDelta = size;
        return rt;
    }

    RectTransform CreateForgeToken(
        Transform parent,
        string name,
        Vector2 anchor,
        Color color,
        out Text tokenText
    )
    {
        RectTransform token = MakePanel(parent, name, color);
        token.anchorMin = token.anchorMax = anchor;
        token.pivot = new Vector2(.5f, .5f);
        token.sizeDelta = new Vector2(126f, 126f);
        token.anchoredPosition = Vector2.zero;
        Frame(token, new Color(.95f, .72f, .26f, 1f), 5f);

        tokenText = MakeText(token, "", 14, TextAnchor.MiddleCenter, true);
        tokenText.color = new Color(1f, .94f, .80f, 1f);
        Anchor(tokenText.rectTransform, .05f, .05f, .95f, .95f);
        return token;
    }

    RectTransform MakeSlotPanel(Transform parent, string name, float x1, float y1, float x2, float y2)
    {
        RectTransform slot = MakePanel(parent, name, new Color(.055f, .050f, .050f, 1f));
        Anchor(slot, x1, y1, x2, y2);
        ApplyPanelSkin(slot, slotSkin);
        if (slotSkin == null)
            Frame(slot, new Color(.38f, .27f, .17f, 1f), 2f);
        return slot;
    }

    void SetMode(ForgeMode next)
    {
        if (probabilityBusy) return;
        mode = next;
        ClearSelection();
        if (resultText != null) resultText.text = "블록을 선택하세요.";
        Refresh();
    }

    void ClearSelection()
    {
        targetId = null;
        materialIds.Clear();
    }

    void Refresh()
    {
        if (panel == null || inventory == null) return;

        RefreshTabs();
        RefreshRules();
        RefreshSharedStorage();
        RefreshSelectionInfo();
    }

    void RefreshTabs()
    {
        SetButtonTone(enhanceTab, mode == ForgeMode.Enhance);
        SetButtonTone(synthesisTab, mode == ForgeMode.Synthesis);
        SetButtonTone(dismantleTab, mode == ForgeMode.Dismantle);
    }

    void SetButtonTone(Button button, bool selected)
    {
        if (button == null) return;
        Image image = button.targetGraphic as Image;
        if (image == null) return;

        Sprite skin = selected ? tabSelectedSkin : tabNormalSkin;
        if (skin != null)
        {
            image.sprite = skin;
            image.type = Image.Type.Sliced;
            image.color = Color.white;
        }
        else
        {
            image.color = selected
                ? new Color(.34f, .16f, .055f, 1f)
                : new Color(.105f, .072f, .060f, 1f);
        }

        Text label = button.GetComponentInChildren<Text>();
        if (label != null)
            label.color = selected
                ? new Color(1f, .90f, .60f, 1f)
                : new Color(.91f, .84f, .73f, 1f);
    }

    void RefreshRules()
    {
        if (ruleText == null) return;

        if (mode == ForgeMode.Enhance)
            ruleText.text = "제물가치  -% 1 · +% 2 · 전용 3 · 수식어 5  |  안전 강화: 가치×10%";
        else if (mode == ForgeMode.Synthesis)
            ruleText.text = "대상 블록 + 제물 블록 1개  ·  성공률 1%  ·  제물의 강화 포함 현재 공/방/체 전부 합산";
        else
            ruleText.text = "제물가치  -% 1 · +% 2 · 전용 3 · 수식어 5  |  분해: 가치×10%";
    }

    void RefreshSharedStorage()
    {
        int heldCount = inventory.GetStorageCount(XTapGearBlockData.LocationHeld, IsForgeListVisible);
        int groundCount = inventory.GetStorageCount(XTapGearBlockData.LocationGround, IsForgeListVisible);
        int heldPages = inventory.GetStoragePageCount(XTapGearBlockData.LocationHeld, IsForgeListVisible);
        int groundPages = inventory.GetStoragePageCount(XTapGearBlockData.LocationGround, IsForgeListVisible);

        heldPage = Mathf.Clamp(heldPage, 0, heldPages - 1);
        groundPage = Mathf.Clamp(groundPage, 0, groundPages - 1);

        if (heldCountText != null) heldCountText.text = "소지품    " + heldCount + "개";
        if (groundCountText != null) groundCountText.text = "바닥    " + groundCount + "개";
        if (heldPageText != null) heldPageText.text = heldCount == 0 ? "0 / 0" : (heldPage + 1) + " / " + heldPages;
        if (groundPageText != null) groundPageText.text = groundCount == 0 ? "0 / 0" : (groundPage + 1) + " / " + groundPages;

        if (heldPrevButton != null) heldPrevButton.interactable = heldPage > 0;
        if (heldNextButton != null) heldNextButton.interactable = heldCount > 0 && heldPage < heldPages - 1;
        if (groundPrevButton != null) groundPrevButton.interactable = groundPage > 0;
        if (groundNextButton != null) groundNextButton.interactable = groundCount > 0 && groundPage < groundPages - 1;

        inventory.RenderSharedStoragePage(
            XTapGearBlockData.LocationHeld,
            heldContent,
            heldPage,
            OnItemPressed,
            IsForgeSelected,
            IsForgeListVisible
        );
        inventory.RenderSharedStoragePage(
            XTapGearBlockData.LocationGround,
            groundContent,
            groundPage,
            OnItemPressed,
            IsForgeSelected,
            IsForgeListVisible
        );
    }

    bool IsForgeSelected(string id)
    {
        return targetId == id || materialIds.Contains(id);
    }

    bool IsForgeListVisible(string id)
    {
        return !IsForgeSelected(id);
    }

    void ClearTargetSelection()
    {
        if (probabilityBusy || string.IsNullOrEmpty(targetId)) return;
        targetId = null;
        Refresh();
    }

    void ClearMaterialSelection()
    {
        if (probabilityBusy || materialIds.Count == 0) return;
        materialIds.Clear();
        Refresh();
    }

    void ChangeStoragePage(int location, int delta)
    {
        if (location == XTapGearBlockData.LocationHeld)
            heldPage = Mathf.Max(0, heldPage + delta);
        else if (location == XTapGearBlockData.LocationGround)
            groundPage = Mathf.Max(0, groundPage + delta);

        RefreshSharedStorage();
    }

    string LocationName(XTapGearBlockData item)
    {
        if (item == null) return "없음";
        if (item.location == XTapGearBlockData.LocationHeld) return "소지품";
        if (item.location == XTapGearBlockData.LocationGround) return "바닥";
        return "장착";
    }

    void OnItemPressed(string id)
    {
        if (string.IsNullOrEmpty(id)) return;
        XTapGearBlockData pressed = inventory.FindForgeItem(id);
        if (pressed == null) return;
        if (pressed.location != XTapGearBlockData.LocationHeld &&
            pressed.location != XTapGearBlockData.LocationGround)
            return;

        if (mode == ForgeMode.Dismantle)
        {
            ToggleMaterial(id, 10);
            Refresh();
            return;
        }

        if (string.IsNullOrEmpty(targetId))
        {
            targetId = id;
            materialIds.Remove(id);
            Refresh();
            return;
        }

        if (targetId == id)
        {
            targetId = null;
            materialIds.Remove(id);
            Refresh();
            return;
        }

        ToggleMaterial(id, mode == ForgeMode.Synthesis ? 1 : 10);
        Refresh();
    }

    void ToggleMaterial(string id, int maxValue)
    {
        if (materialIds.Contains(id))
        {
            materialIds.Remove(id);
            return;
        }

        if (mode == ForgeMode.Synthesis)
        {
            if (materialIds.Count >= maxValue)
            {
                if (resultText != null)
                    resultText.text = "합성 제물은 1개만 선택할 수 있습니다.";
                return;
            }

            materialIds.Add(id);
            return;
        }

        XTapGearBlockData material = inventory.FindForgeItem(id);
        if (material == null) return;

        int currentValue = GetSelectedSacrificeValue();
        int addedValue = GetSacrificeValue(material);
        if (currentValue + addedValue > maxValue)
        {
            if (resultText != null)
                resultText.text =
                    "제물 가치는 최대 " + maxValue + "입니다.  현재 " +
                    currentValue + " + 선택 블럭 " + addedValue;
            return;
        }

        materialIds.Add(id);
    }

    int GetSacrificeValue(XTapGearBlockData item)
    {
        if (item == null) return 0;

        // Highest applicable tier wins so a rare block is never valued below
        // one of its lower traits.
        if (item.descriptorCount > 0) return 5;
        if (item.exclusive) return 3;
        if (item.correction > 0) return 2;

        // Negative-correction blocks are worth 1. A plain 0% non-exclusive
        // ticket block also falls back to 1 so every valid block can be used.
        return 1;
    }

    int GetSelectedSacrificeValue()
    {
        int total = 0;
        for (int i = 0; i < materialIds.Count; i++)
        {
            XTapGearBlockData item = inventory.FindForgeItem(materialIds[i]);
            total += GetSacrificeValue(item);
        }
        return total;
    }

    void RefreshSelectionInfo()
    {
        XTapGearBlockData target = inventory.FindForgeItem(targetId);

        if (targetSlot != null)
            targetSlot.gameObject.SetActive(mode != ForgeMode.Dismantle);

        if (materialSlot != null)
        {
            if (mode == ForgeMode.Dismantle)
                Anchor(materialSlot, .18f, .595f, .82f, .805f);
            else
                Anchor(materialSlot, .535f, .595f, .945f, .805f);
        }

        if (targetSlotText != null)
        {
            targetSlotText.text = target == null
                ? "+"
                : XTapGearNameColor.Rich(target) +
                  (target.enhanceLevel > 0 ? "  +" + target.enhanceLevel : "") +
                  "\n" + XTapStatFormat.BlockTriplet(target.attack, target.defense, target.hp, "   ");
        }

        double sacrificeAttack = 0d;
        double sacrificeDefense = 0d;
        double sacrificeHp = 0d;
        int sacrificeCount = 0;
        int sacrificeValue = 0;
        XTapGearBlockData singleSacrifice = null;

        for (int i = 0; i < materialIds.Count; i++)
        {
            XTapGearBlockData material = inventory.FindForgeItem(materialIds[i]);
            if (material == null) continue;

            sacrificeCount++;
            sacrificeValue += GetSacrificeValue(material);
            sacrificeAttack = XTapStatFormat.SafeAdd(sacrificeAttack, Math.Max(0d, material.attack));
            sacrificeDefense = XTapStatFormat.SafeAdd(sacrificeDefense, Math.Max(0d, material.defense));
            sacrificeHp = XTapStatFormat.SafeAdd(sacrificeHp, Math.Max(0d, material.hp));
            if (sacrificeCount == 1)
                singleSacrifice = material;
        }

        if (materialSlotText != null)
        {
            if (sacrificeCount == 0)
            {
                materialSlotText.text = "+";
            }
            else if (sacrificeCount == 1 && singleSacrifice != null)
            {
                materialSlotText.text =
                    XTapGearNameColor.Rich(singleSacrifice) +
                    (singleSacrifice.enhanceLevel > 0 ? "  +" + singleSacrifice.enhanceLevel : "") +
                    "\n제물 " + GetSacrificeValue(singleSacrifice) + "개분  ·  " +
                    XTapStatFormat.BlockTriplet(singleSacrifice.attack, singleSacrifice.defense, singleSacrifice.hp, "   ");
            }
            else
            {
                materialSlotText.text =
                    "블럭 " + sacrificeCount + "개  ·  제물가치 " + sacrificeValue + "/10" +
                    "\n합계  " + XTapStatFormat.BlockTriplet(sacrificeAttack, sacrificeDefense, sacrificeHp, "   ");
            }
        }

        if (mode == ForgeMode.Enhance)
        {
            bool destructive = target != null && target.enhanceLevel >= 10;
            int chance = destructive ? 10 : Mathf.Clamp(sacrificeValue * 10, 0, 100);
            selectionText.text = destructive
                ? "파괴 강화  +" + (target.enhanceLevel + 1) + "  ·  제물가치 " + sacrificeValue
                : "안전 강화  +" + (target != null ? target.enhanceLevel + 1 : 1) + "  ·  제물가치 " + sacrificeValue + "/10";
            chanceText.text = destructive
                ? "성공률 10%  ·  실패 시 대상 파괴"
                : "성공률 " + chance + "%  ·  실패 시 대상 유지";
            executeButton.interactable = target != null && sacrificeValue > 0 && target.enhanceLevel < 20;
        }
        else if (mode == ForgeMode.Synthesis)
        {
            selectionText.text = sacrificeCount == 1 ? "대상 + 제물 준비" : "대상 + 제물 1개";
            chanceText.text = "성공률 1%";
            executeButton.interactable = target != null && sacrificeCount == 1;
        }
        else
        {
            int chance = Mathf.Clamp(sacrificeValue * 10, 0, 100);
            selectionText.text = "제물가치 " + sacrificeValue + "/10  ·  블럭 " + sacrificeCount + "개";
            chanceText.text = "가방 +1칸  " + chance + "%";
            executeButton.interactable = sacrificeValue > 0;
        }
    }

    string ItemName(string id)
    {
        XTapGearBlockData item = inventory.FindForgeItem(id);
        return item == null ? "없음" : item.displayName;
    }

    void Execute()
    {
        if (inventory == null || probabilityBusy) return;

        int chance;
        if (!TryGetCurrentOperationChance(out chance))
            return;

        if (probabilityRoutine != null)
            StopCoroutine(probabilityRoutine);

        probabilityRoutine = StartCoroutine(RunProbabilityMachine(mode, chance));
    }

    bool TryGetCurrentOperationChance(out int chance)
    {
        chance = 0;
        int sacrificeValue = GetSelectedSacrificeValue();

        if (mode == ForgeMode.Enhance)
        {
            XTapGearBlockData target = inventory.FindForgeItem(targetId);
            if (target == null || materialIds.Count == 0)
            {
                resultText.text = "대상과 재료를 선택하세요.";
                return false;
            }

            if (target.enhanceLevel >= 20)
            {
                resultText.text = "이미 +20 최대 강화입니다.";
                return false;
            }

            chance = target.enhanceLevel >= 10
                ? 10
                : Mathf.Clamp(sacrificeValue * 10, 0, 100);
            return true;
        }

        if (mode == ForgeMode.Synthesis)
        {
            XTapGearBlockData target = inventory.FindForgeItem(targetId);
            if (target == null || materialIds.Count != 1)
            {
                resultText.text = "대상 1개와 재료 1개를 선택하세요.";
                return false;
            }

            XTapGearBlockData material = inventory.FindForgeItem(materialIds[0]);
            if (material == null)
            {
                resultText.text = "재료 블록을 찾을 수 없습니다.";
                ClearSelection();
                Refresh();
                return false;
            }

            chance = 1;
            return true;
        }

        if (materialIds.Count <= 0)
        {
            resultText.text = "분해할 재료를 선택하세요.";
            return false;
        }

        chance = Mathf.Clamp(sacrificeValue * 10, 0, 100);
        return true;
    }

    IEnumerator RunProbabilityMachine(ForgeMode operationMode, int chance)
    {
        probabilityBusy = true;
        if (executeButton != null) executeButton.interactable = false;

        probabilityOverlay.SetActive(true);
        probabilityOverlay.transform.SetAsLastSibling();

        string operationName = operationMode == ForgeMode.Enhance
            ? "강화"
            : (operationMode == ForgeMode.Synthesis ? "합성" : "분해");

        XTapGearBlockData enhanceTarget = operationMode == ForgeMode.Enhance
            ? inventory.FindForgeItem(targetId)
            : null;
        bool destructiveEnhance = enhanceTarget != null && enhanceTarget.enhanceLevel >= 10;

        probabilityTitleText.text = "X-TOWER  " + operationName;
        probabilityChanceText.text = "성공률 " + chance + "%";
        probabilityPhaseText.text = "천사와 악마가 결과를 다툽니다";
        probabilityPhaseText.color = new Color(.94f, .85f, .66f, 1f);
        probabilityResultText.text = "";

        // Probability is decided exactly once before the presentation starts.
        // The final hammer blow only REVEALS that already-decided outcome.
        int finalRoll = UnityEngine.Random.Range(0, 100);
        bool success = finalRoll < chance;

        probabilityMachine.localScale = Vector3.one;
        probabilityMachine.anchoredPosition = Vector2.zero;
        forgeStage.anchoredPosition = Vector2.zero;

        ResetForgeDuelStage(operationMode);
        yield return AnimateForgeIntro(operationMode);

        // Six alternating blows create anticipation. The opponent always gets
        // the last pre-hit, then the actual winning side delivers the finisher.
        for (int i = 0; i < 6; i++)
        {
            bool angelHit = (i % 2 == 0) ? success : !success;
            float strikeDuration = Mathf.Lerp(.30f, .15f, i / 5f);
            yield return ForgeHammerStrike(angelHit, false, strikeDuration);
        }

        probabilityPhaseText.text = "마지막 일격";
        probabilityPhaseText.color = new Color(1f, .90f, .58f, 1f);
        yield return new WaitForSecondsRealtime(.34f);

        // Angel finisher = success, demon finisher = failure.
        yield return ForgeHammerStrike(success, true, .34f);

        probabilityPhaseText.text = destructiveEnhance && !success
            ? "대상 파괴"
            : (success ? "천사의 막타" : "악마의 막타");
        probabilityPhaseText.color = success
            ? new Color(.72f, .91f, 1f, 1f)
            : new Color(1f, .42f, .32f, 1f);

        probabilityResultText.text = success ? "성공" : "실패";
        probabilityResultText.color = success
            ? new Color(1f, .88f, .38f, 1f)
            : new Color(1f, .28f, .22f, 1f);

        VibrateForgeResult();
        yield return AnimateForgeOutcome(operationMode, success);
        yield return new WaitForSecondsRealtime(.52f);

        if (operationMode == ForgeMode.Enhance)
            ResolveEnhance(success);
        else if (operationMode == ForgeMode.Synthesis)
            ResolveSynthesis(success);
        else
            ResolveDismantle(success);

        probabilityOverlay.SetActive(false);
        probabilityBusy = false;
        probabilityRoutine = null;
        Refresh();
    }

    void ResetForgeDuelStage(ForgeMode operationMode)
    {
        if (angelSmith != null)
        {
            angelSmith.anchoredPosition = angelRestPosition;
            angelSmith.localRotation = Quaternion.identity;
            angelSmith.localScale = Vector3.one;
        }

        if (demonSmith != null)
        {
            demonSmith.anchoredPosition = demonRestPosition;
            demonSmith.localRotation = Quaternion.identity;
            demonSmith.localScale = Vector3.one;
        }

        if (forgeAnvil != null)
        {
            forgeAnvil.anchoredPosition = new Vector2(0f, -8f);
            forgeAnvil.localScale = Vector3.one;
        }

        if (forgeImpactImage != null)
            forgeImpactImage.color = new Color(1f, 1f, 1f, 0f);
        if (forgeImpact != null)
            forgeImpact.localScale = Vector3.one * .15f;

        XTapGearBlockData target = inventory.FindForgeItem(targetId);
        bool showTarget = operationMode != ForgeMode.Dismantle;
        bool showMaterial = operationMode != ForgeMode.Enhance;

        forgeTargetToken.gameObject.SetActive(showTarget);
        forgeMaterialToken.gameObject.SetActive(showMaterial);

        if (showTarget)
        {
            forgeTargetToken.localScale = Vector3.one;
            forgeTargetToken.anchoredPosition = operationMode == ForgeMode.Synthesis
                ? new Vector2(-82f, -36f)
                : new Vector2(0f, -36f);

            forgeTargetTokenText.text = operationMode == ForgeMode.Enhance
                ? (target != null ? "+" + target.enhanceLevel : "대상")
                : "대상";
        }

        if (showMaterial)
        {
            forgeMaterialToken.localScale = Vector3.one;
            forgeMaterialToken.anchoredPosition = operationMode == ForgeMode.Synthesis
                ? new Vector2(82f, -36f)
                : new Vector2(0f, -36f);

            forgeMaterialTokenText.text = operationMode == ForgeMode.Dismantle
                ? "제물 " + GetSelectedSacrificeValue()
                : "제물";
        }
    }

    IEnumerator AnimateForgeIntro(ForgeMode operationMode)
    {
        Vector3 angelStart = Vector3.one * .84f;
        Vector3 demonStart = Vector3.one * .84f;
        angelSmith.localScale = angelStart;
        demonSmith.localScale = demonStart;

        Vector2 targetEnd = forgeTargetToken.gameObject.activeSelf
            ? forgeTargetToken.anchoredPosition
            : Vector2.zero;
        Vector2 materialEnd = forgeMaterialToken.gameObject.activeSelf
            ? forgeMaterialToken.anchoredPosition
            : Vector2.zero;

        if (forgeTargetToken.gameObject.activeSelf)
            forgeTargetToken.anchoredPosition = targetEnd + Vector2.down * 90f;
        if (forgeMaterialToken.gameObject.activeSelf)
            forgeMaterialToken.anchoredPosition = materialEnd + Vector2.down * 90f;

        float t = 0f;
        const float duration = .34f;
        while (t < duration)
        {
            t += Time.unscaledDeltaTime;
            float p = Mathf.Clamp01(t / duration);
            float e = 1f - Mathf.Pow(1f - p, 3f);

            angelSmith.localScale = Vector3.Lerp(angelStart, Vector3.one, e);
            demonSmith.localScale = Vector3.Lerp(demonStart, Vector3.one, e);

            if (forgeTargetToken.gameObject.activeSelf)
                forgeTargetToken.anchoredPosition = Vector2.Lerp(
                    targetEnd + Vector2.down * 90f,
                    targetEnd,
                    e
                );
            if (forgeMaterialToken.gameObject.activeSelf)
                forgeMaterialToken.anchoredPosition = Vector2.Lerp(
                    materialEnd + Vector2.down * 90f,
                    materialEnd,
                    e
                );

            yield return null;
        }

        angelSmith.localScale = Vector3.one;
        demonSmith.localScale = Vector3.one;
        if (forgeTargetToken.gameObject.activeSelf)
            forgeTargetToken.anchoredPosition = targetEnd;
        if (forgeMaterialToken.gameObject.activeSelf)
            forgeMaterialToken.anchoredPosition = materialEnd;

        if (operationMode == ForgeMode.Synthesis)
        {
            probabilityPhaseText.text = "두 블록을 하나의 운명으로";
            yield return new WaitForSecondsRealtime(.18f);
        }
    }

    IEnumerator ForgeHammerStrike(bool angelHit, bool finalHit, float duration)
    {
        RectTransform smith = angelHit ? angelSmith : demonSmith;
        Vector2 home = angelHit ? angelRestPosition : demonRestPosition;
        float side = angelHit ? 1f : -1f;

        probabilityPhaseText.text = finalHit
            ? "마지막 일격"
            : (angelHit ? "천사의 망치" : "악마의 망치");
        probabilityPhaseText.color = angelHit
            ? new Color(.72f, .90f, 1f, 1f)
            : new Color(1f, .45f, .36f, 1f);

        float liftDuration = duration * .48f;
        float t = 0f;
        Vector2 lifted = home + new Vector2(-side * 14f, finalHit ? 48f : 30f);
        float raisedAngle = angelHit ? 8f : -8f;

        while (t < liftDuration)
        {
            t += Time.unscaledDeltaTime;
            float p = Mathf.Clamp01(t / liftDuration);
            float e = p * p * (3f - 2f * p);
            smith.anchoredPosition = Vector2.Lerp(home, lifted, e);
            smith.localRotation = Quaternion.Euler(0f, 0f, raisedAngle * e);
            yield return null;
        }

        float dropDuration = Mathf.Max(.05f, duration - liftDuration);
        t = 0f;
        Vector2 strike = home + new Vector2(side * (finalHit ? 58f : 38f), finalHit ? -48f : -28f);
        float strikeAngle = angelHit ? -12f : 12f;

        while (t < dropDuration)
        {
            t += Time.unscaledDeltaTime;
            float p = Mathf.Clamp01(t / dropDuration);
            float e = 1f - Mathf.Pow(1f - p, 4f);
            smith.anchoredPosition = Vector2.Lerp(lifted, strike, e);
            smith.localRotation = Quaternion.Euler(
                0f,
                0f,
                Mathf.Lerp(raisedAngle, strikeAngle, e)
            );

            if (p > .58f)
            {
                float hitP = Mathf.InverseLerp(.58f, 1f, p);
                float flash = Mathf.Sin(hitP * Mathf.PI);
                forgeImpactImage.color = angelHit
                    ? new Color(1f, .88f, .32f, flash)
                    : new Color(1f, .16f, .10f, flash);
                forgeImpact.localScale = Vector3.one * Mathf.Lerp(
                    .25f,
                    finalHit ? 1.75f : 1.10f,
                    hitP
                );

                float shake = (finalHit ? 16f : 7f) * (1f - hitP);
                forgeStage.anchoredPosition = new Vector2(
                    Mathf.Sin(Time.unscaledTime * 95f) * shake,
                    Mathf.Cos(Time.unscaledTime * 73f) * shake * .38f
                );
                forgeAnvil.localScale = Vector3.one * (1f + flash * (finalHit ? .08f : .035f));
            }

            yield return null;
        }

        smith.anchoredPosition = home;
        smith.localRotation = Quaternion.identity;
        forgeStage.anchoredPosition = Vector2.zero;
        forgeAnvil.localScale = Vector3.one;
        forgeImpactImage.color = new Color(1f, 1f, 1f, 0f);
        forgeImpact.localScale = Vector3.one * .15f;

        if (finalHit)
            yield return new WaitForSecondsRealtime(.12f);
    }

    IEnumerator AnimateForgeOutcome(ForgeMode operationMode, bool success)
    {
        if (operationMode == ForgeMode.Synthesis &&
            forgeTargetToken.gameObject.activeSelf &&
            forgeMaterialToken.gameObject.activeSelf)
        {
            Vector2 targetStart = forgeTargetToken.anchoredPosition;
            Vector2 materialStart = forgeMaterialToken.anchoredPosition;
            float t = 0f;
            const float duration = .30f;

            while (t < duration)
            {
                t += Time.unscaledDeltaTime;
                float p = Mathf.Clamp01(t / duration);
                float e = 1f - Mathf.Pow(1f - p, 3f);
                forgeTargetToken.anchoredPosition = Vector2.Lerp(targetStart, Vector2.zero, e);
                forgeMaterialToken.anchoredPosition = Vector2.Lerp(materialStart, Vector2.zero, e);
                forgeTargetToken.localScale = Vector3.one * Mathf.Lerp(1f, success ? 1.18f : .72f, e);
                forgeMaterialToken.localScale = Vector3.one * Mathf.Lerp(1f, success ? .18f : .55f, e);
                yield return null;
            }

            forgeMaterialToken.gameObject.SetActive(false);
            forgeTargetToken.localScale = Vector3.one * (success ? 1.18f : .72f);
        }
        else
        {
            RectTransform token = operationMode == ForgeMode.Dismantle
                ? forgeMaterialToken
                : forgeTargetToken;

            if (token != null && token.gameObject.activeSelf)
            {
                Vector3 start = token.localScale;
                Vector3 peak = Vector3.one * (success ? 1.22f : .72f);
                float t = 0f;
                const float duration = .24f;

                while (t < duration)
                {
                    t += Time.unscaledDeltaTime;
                    float p = Mathf.Clamp01(t / duration);
                    token.localScale = Vector3.Lerp(start, peak, p);
                    yield return null;
                }
            }
        }
    }

    static float NormalizeSignedAngle(float angle)
    {
        return Mathf.Repeat(angle + 180f, 360f) - 180f;
    }

    void VibrateForgeResult()
    {
#if UNITY_ANDROID && !UNITY_EDITOR
        if (PlayerPrefs.GetInt("xtap_option_vibration", 1) == 1)
            Handheld.Vibrate();
#endif
    }

    void ResolveEnhance(bool success)
    {
        XTapGearBlockData target = inventory.FindForgeItem(targetId);
        if (target == null)
        {
            resultText.text = "강화 대상을 찾을 수 없습니다.";
            ClearSelection();
            return;
        }

        int materialCount = materialIds.Count;
        bool destructive = target.enhanceLevel >= 10;
        inventory.EnsureEnhancementBaseStats(target);
        ConsumeMaterials();

        if (success)
        {
            target.enhanceLevel++;
            inventory.RecalculateEnhancedStats(target);
            inventory.CommitForgeChanges();
            resultText.text =
                "강화 성공!  +" + target.enhanceLevel + "   " +
                XTapStatFormat.BlockTriplet(target.attack, target.defense, target.hp, " / ");
        }
        else if (destructive)
        {
            string destroyedName = XTapGearNameColor.Rich(target);
            inventory.RemoveForgeItem(target.id);
            inventory.CommitForgeChanges();
            resultText.text =
                "강화 실패. " + destroyedName + "이(가) 파괴되었습니다.  제물 " +
                materialCount + "개 소모";
        }
        else
        {
            inventory.CommitForgeChanges();
            resultText.text =
                "강화 실패. 대상은 유지됩니다.  제물 " + materialCount + "개 소모";
        }

        ClearSelection();
    }

    void ResolveSynthesis(bool success)
    {
        XTapGearBlockData target = inventory.FindForgeItem(targetId);
        XTapGearBlockData material = materialIds.Count == 1
            ? inventory.FindForgeItem(materialIds[0])
            : null;

        if (target == null || material == null)
        {
            resultText.text = "합성 대상 또는 재료를 찾을 수 없습니다.";
            ClearSelection();
            return;
        }

        double addAttack;
        double addDefense;
        double addHp;
        inventory.GetPreDescriptorStats(material, out addAttack, out addDefense, out addHp);
        string consumedName = XTapGearNameColor.Rich(material);

        inventory.RemoveForgeItem(material.id);

        if (success)
        {
            inventory.MergeSynthesisStats(target, addAttack, addDefense, addHp);
            inventory.CommitForgeChanges();

            resultText.text =
                "합성 성공!  " + consumedName + " 능력을 흡수했습니다.  합성 후 " +
                XTapStatFormat.BlockTriplet(target.attack, target.defense, target.hp, " / ");
        }
        else
        {
            inventory.CommitForgeChanges();
            resultText.text = "합성 실패. " + consumedName + "이(가) 소모됐습니다.";
        }

        ClearSelection();
    }

    void ResolveDismantle(bool success)
    {
        int count = materialIds.Count;
        ConsumeMaterials();

        if (success)
        {
            inventory.AddGridCellExpansion(1);
            resultText.text =
                "분해 성공! 가방 배치칸 +1.  현재 " + inventory.GridCapacity + "칸";
        }
        else
        {
            inventory.CommitForgeChanges();
            resultText.text =
                "분해 실패. 재료 " + count + "개가 모두 소모됐습니다.";
        }

        ClearSelection();
    }

    void ConsumeMaterials()
    {
        string[] ids = materialIds.ToArray();

        for (int i = 0; i < ids.Length; i++)
        {
            if (ids[i] == targetId) continue;
            inventory.RemoveForgeItem(ids[i]);
        }
    }

    void LoadVisualAssets()
    {
        LoadForgeDuelAssets();

        try
        {
            byte[] bytes = null;
            TextAsset encoded = Resources.Load<TextAsset>("XTapBlacksmithUI/atlas");

            if (encoded != null && !string.IsNullOrWhiteSpace(encoded.text))
            {
                try
                {
                    bytes = Convert.FromBase64String(encoded.text.Trim());
                }
                catch
                {
                    bytes = null;
                }
            }

            // 11.40: guaranteed runtime fallback for the existing blacksmith atlas.
            if (bytes == null || bytes.Length < 1024)
            {
                bytes = Convert.FromBase64String(EmbeddedBlacksmithAtlasJpegBase64);
                Debug.LogWarning("X탑 대장간 atlas Resources 로드 실패. 내장 이미지 fallback 사용.");
            }

            skinAtlas = new Texture2D(2, 2, TextureFormat.RGB24, false);
            if (!skinAtlas.LoadImage(bytes, false))
            {
                Destroy(skinAtlas);
                skinAtlas = null;
                Debug.LogError("X탑 대장간 atlas 이미지 최종 로드 실패.");
                return;
            }

            skinAtlas.wrapMode = TextureWrapMode.Clamp;
            skinAtlas.filterMode = FilterMode.Bilinear;

            // Atlas is 256x512. Coordinates below use top-left design coordinates.
            backgroundSkin = MakeAtlasSprite(0, 0, 144, 256, Vector4.zero);
            panelSkin = MakeAtlasSprite(144, 0, 112, 84, new Vector4(18f, 18f, 18f, 18f));
            slotSkin = MakeAtlasSprite(144, 84, 112, 112, new Vector4(18f, 18f, 18f, 18f));
            tabNormalSkin = MakeAtlasSprite(0, 256, 128, 43, new Vector4(22f, 10f, 22f, 10f));
            tabSelectedSkin = MakeAtlasSprite(128, 256, 128, 43, new Vector4(22f, 10f, 22f, 10f));
            buttonNeutralSkin = MakeAtlasSprite(0, 299, 128, 43, new Vector4(22f, 10f, 22f, 10f));
            buttonPrimarySkin = MakeAtlasSprite(128, 299, 128, 43, new Vector4(22f, 10f, 22f, 10f));
            statusBarSkin = MakeAtlasSprite(0, 406, 256, 64, new Vector4(26f, 12f, 26f, 12f));
        }
        catch (Exception e)
        {
            Debug.LogError("X탑 대장간 UI 에셋 로드 실패: " + e.Message);
        }
    }

    void LoadForgeDuelAssets()
    {
        try
        {
            TextAsset backgroundBytes = Resources.Load<TextAsset>(
                "XTapBlacksmithUI/forge_duel_background"
            );
            forgeDuelBackgroundTexture = new Texture2D(
                2,
                2,
                TextureFormat.RGB24,
                false
            );

            if (!LoadImageBytes(forgeDuelBackgroundTexture, backgroundBytes))
            {
                Destroy(forgeDuelBackgroundTexture);
                forgeDuelBackgroundTexture = null;
                Debug.LogError("X탑 대장간 9:16 듀얼 배경 로드 실패.");
            }
            else
            {
                forgeDuelBackgroundTexture.wrapMode = TextureWrapMode.Clamp;
                forgeDuelBackgroundTexture.filterMode = FilterMode.Bilinear;
                forgeDuelBackgroundSkin = Sprite.Create(
                    forgeDuelBackgroundTexture,
                    new Rect(
                        0f,
                        0f,
                        forgeDuelBackgroundTexture.width,
                        forgeDuelBackgroundTexture.height
                    ),
                    new Vector2(.5f, .5f),
                    100f
                );
                forgeDuelBackgroundSkin.name = "XTapForgeDuelBackground";
            }

            TextAsset atlasBytes = Resources.Load<TextAsset>(
                "XTapBlacksmithUI/forge_duel_atlas"
            );
            forgeDuelAtlasTexture = new Texture2D(
                2,
                2,
                TextureFormat.RGBA32,
                false
            );

            if (!LoadImageBytes(forgeDuelAtlasTexture, atlasBytes))
            {
                Destroy(forgeDuelAtlasTexture);
                forgeDuelAtlasTexture = null;
                Debug.LogError("X탑 대장간 천사/악마/모루 atlas 로드 실패.");
            }
            else
            {
                forgeDuelAtlasTexture.wrapMode = TextureWrapMode.Clamp;
                forgeDuelAtlasTexture.filterMode = FilterMode.Bilinear;

                // Coordinates use top-left atlas design coordinates.
                angelSmithSkin = MakeForgeDuelAtlasSprite(5, 48, 150, 199);
                demonSmithSkin = MakeForgeDuelAtlasSprite(175, 48, 155, 199);
                forgeAnvilSkin = MakeForgeDuelAtlasSprite(346, 130, 160, 85);
            }
        }
        catch (Exception e)
        {
            Debug.LogError("X탑 대장간 듀얼 에셋 로드 실패: " + e.Message);
        }
    }

    Sprite MakeForgeDuelAtlasSprite(
        int x,
        int yFromTop,
        int width,
        int height
    )
    {
        if (forgeDuelAtlasTexture == null) return null;

        int safeX = Mathf.Clamp(x, 0, forgeDuelAtlasTexture.width - 1);
        int safeWidth = Mathf.Clamp(
            width,
            1,
            forgeDuelAtlasTexture.width - safeX
        );
        int safeHeight = Mathf.Clamp(
            height,
            1,
            forgeDuelAtlasTexture.height
        );
        int y = forgeDuelAtlasTexture.height - yFromTop - safeHeight;
        y = Mathf.Clamp(y, 0, forgeDuelAtlasTexture.height - safeHeight);

        return Sprite.Create(
            forgeDuelAtlasTexture,
            new Rect(safeX, y, safeWidth, safeHeight),
            new Vector2(.5f, .5f),
            100f,
            0,
            SpriteMeshType.FullRect
        );
    }

    void LoadProbabilityWheelAsset()
    {
        try
        {
            probabilityWheelTexture = new Texture2D(2, 2, TextureFormat.RGBA32, false);

            // 11.44: approved SUCCESS/FAIL art is primary so stale Android Resources
            // can never hide the roulette.
            bool loaded = false;
            try
            {
                loaded = probabilityWheelTexture.LoadImage(
                    Convert.FromBase64String(EmbeddedForgeWheelJpegBase64),
                    false
                );
            }
            catch
            {
                loaded = false;
            }

            if (!loaded)
            {
                TextAsset wheelBytes = Resources.Load<TextAsset>("XTapBlacksmithUI/forge_success_fail_wheel");
                if (wheelBytes != null)
                {
                    try
                    {
                        loaded = LoadImageBytes(probabilityWheelTexture, wheelBytes);
                    }
                    catch
                    {
                        loaded = false;
                    }
                }
            }

            if (!loaded)
            {
                Destroy(probabilityWheelTexture);
                probabilityWheelTexture = null;
                Debug.LogError("X탑 대장간 SUCCESS/FAIL 룰렛 이미지 최종 로드 실패.");
                return;
            }

            probabilityWheelTexture.wrapMode = TextureWrapMode.Clamp;
            probabilityWheelTexture.filterMode = FilterMode.Bilinear;

            // The authored forge asset is circular. Force every pixel outside the
            // circle transparent so a JPEG/opaque source can never rotate as a white square.
            probabilityWheelTexture = CreateCircularRgbaTexture(probabilityWheelTexture);

            probabilityWheelSkin = Sprite.Create(
                probabilityWheelTexture,
                new Rect(0f, 0f, probabilityWheelTexture.width, probabilityWheelTexture.height),
                new Vector2(.5f, .5f),
                100f
            );
            probabilityWheelSkin.name = "XTapForgeSuccessFailWheel";
        }
        catch (Exception e)
        {
            Debug.LogError("X탑 대장간 SUCCESS/FAIL 룰렛 에셋 로드 실패: " + e.Message);
        }
    }

    bool LoadImageBytes(Texture2D texture, TextAsset source)
    {
        if (texture == null || source == null) return false;

        if (source.bytes != null && source.bytes.Length > 0 &&
            texture.LoadImage(source.bytes, false))
            return true;

        try
        {
            string encoded = source.text != null ? source.text.Trim() : "";
            if (string.IsNullOrEmpty(encoded)) return false;
            byte[] bytes = Convert.FromBase64String(encoded);
            return texture.LoadImage(bytes, false);
        }
        catch
        {
            return false;
        }
    }

    static Texture2D CreateCircularRgbaTexture(Texture2D source)
    {
        if (source == null || !source.isReadable) return source;

        int w = source.width;
        int h = source.height;
        Color32[] pixels = source.GetPixels32();
        Texture2D texture = new Texture2D(w, h, TextureFormat.RGBA32, false);
        texture.wrapMode = TextureWrapMode.Clamp;
        texture.filterMode = FilterMode.Bilinear;
        float cx = (w - 1) * .5f;
        float cy = (h - 1) * .5f;
        float radius = Mathf.Min(w, h) * .498f;
        float feather = Mathf.Max(1f, Mathf.Min(w, h) * .018f);
        float solidRadius = radius - feather;

        for (int y = 0; y < h; y++)
        {
            float dy = y - cy;
            for (int x = 0; x < w; x++)
            {
                float dx = x - cx;
                float d = Mathf.Sqrt(dx * dx + dy * dy);
                int i = y * w + x;

                if (d >= radius)
                {
                    pixels[i].a = 0;
                }
                else if (d > solidRadius)
                {
                    float edge = Mathf.Clamp01((radius - d) / feather);
                    pixels[i].a = (byte)Mathf.RoundToInt(pixels[i].a * edge);
                }
            }
        }

        texture.SetPixels32(pixels);
        texture.Apply(false, false);
        UnityEngine.Object.Destroy(source);
        return texture;
    }

    Sprite MakeAtlasSprite(int x, int yFromTop, int width, int height, Vector4 border)
    {
        if (skinAtlas == null) return null;

        int y = skinAtlas.height - yFromTop - height;
        Rect rect = new Rect(x, y, width, height);
        return Sprite.Create(
            skinAtlas,
            rect,
            new Vector2(.5f, .5f),
            100f,
            0,
            SpriteMeshType.FullRect,
            border
        );
    }

    void ApplyPanelSkin(RectTransform rect, Sprite skin)
    {
        if (rect == null || skin == null) return;
        Image image = rect.GetComponent<Image>();
        if (image == null) return;

        image.sprite = skin;
        image.type = Image.Type.Sliced;
        image.color = Color.white;
    }

    void ApplyButtonSkin(Button button, Sprite skin)
    {
        if (button == null || skin == null) return;
        Image image = button.targetGraphic as Image;
        if (image == null) return;

        image.sprite = skin;
        image.type = Image.Type.Sliced;
        image.color = Color.white;
    }

    RectTransform MakePanel(Transform parent, string name, Color color)
    {
        GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
        go.transform.SetParent(parent, false);

        Image image = go.GetComponent<Image>();
        image.color = color;
        image.raycastTarget = false;
        return image.rectTransform;
    }

    Button MakeButton(Transform parent, string label, int fontSize, Color color)
    {
        GameObject go = new GameObject(label + "Button", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image), typeof(Button));
        go.transform.SetParent(parent, false);

        Image bg = go.GetComponent<Image>();
        bg.color = color;

        RectTransform accent = MakePanel(go.transform, "TypeAccent", new Color(.72f, .43f, .18f, .95f));
        Anchor(accent, .18f, .90f, .82f, .925f);
        accent.GetComponent<Image>().raycastTarget = false;

        Text t = MakeText(go.transform, label, fontSize + 1, TextAnchor.MiddleCenter, true);
        t.color = new Color(1f, .91f, .78f, 1f);
        Outline outline = t.gameObject.AddComponent<Outline>();
        outline.effectColor = new Color(0f, 0f, 0f, .90f);
        outline.effectDistance = new Vector2(2f, -2f);
        Anchor(t.rectTransform, .04f, .04f, .96f, .90f);

        Button b = go.GetComponent<Button>();
        b.targetGraphic = bg;

        ColorBlock cb = b.colors;
        cb.normalColor = Color.white;
        cb.highlightedColor = new Color(1f, .92f, .78f, 1f);
        cb.pressedColor = new Color(.62f, .43f, .30f, 1f);
        cb.selectedColor = Color.white;
        cb.fadeDuration = .06f;
        b.colors = cb;

        return b;
    }

    Text MakeText(Transform parent, string value, int size, TextAnchor align, bool bold)
    {
        GameObject go = new GameObject("Text", typeof(RectTransform), typeof(CanvasRenderer), typeof(Text));
        go.transform.SetParent(parent, false);

        Text t = go.GetComponent<Text>();
        t.text = value;
        t.font = font;
        t.fontSize = Mathf.RoundToInt(size * UiFontScale);
        t.alignment = align;
        t.fontStyle = bold ? FontStyle.Bold : FontStyle.Normal;
        t.supportRichText = true;
        t.horizontalOverflow = HorizontalWrapMode.Wrap;
        t.verticalOverflow = VerticalWrapMode.Truncate;
        t.raycastTarget = false;
        return t;
    }

    void Frame(RectTransform parent, Color color, float thickness)
    {
        RectTransform top = MakePanel(parent, "FrameTop", color);
        Anchor(top, 0f, 1f, 1f, 1f);
        top.sizeDelta = new Vector2(0f, thickness);

        RectTransform bottom = MakePanel(parent, "FrameBottom", color);
        Anchor(bottom, 0f, 0f, 1f, 0f);
        bottom.sizeDelta = new Vector2(0f, thickness);

        RectTransform left = MakePanel(parent, "FrameLeft", color);
        Anchor(left, 0f, 0f, 0f, 1f);
        left.sizeDelta = new Vector2(thickness, 0f);

        RectTransform right = MakePanel(parent, "FrameRight", color);
        Anchor(right, 1f, 0f, 1f, 1f);
        right.sizeDelta = new Vector2(thickness, 0f);
    }

    static void Anchor(RectTransform r, float x1, float y1, float x2, float y2)
    {
        r.anchorMin = new Vector2(x1, y1);
        r.anchorMax = new Vector2(x2, y2);
        r.offsetMin = Vector2.zero;
        r.offsetMax = Vector2.zero;
    }
}
